/* Vocabulary from the North Creek study guide, plus Forever Dates. */
window.VOCAB = [
  // L1 Colonies
  { l: 'l01', term: 'New England Colonies', def: 'Massachusetts, Connecticut, Rhode Island and New Hampshire. Settled by Puritan families; small farms, fishing, shipbuilding and trade; town meetings.', why: 'Least religiously tolerant and least stratified region; a model of local self-government.' },
  { l: 'l01', term: 'Middle Colonies', def: 'New York, New Jersey, Pennsylvania and Delaware. Grew cereal crops (the “breadbasket”); the most ethnically and religiously diverse region.', why: 'Most tolerant region (Quaker Pennsylvania); moderate social stratification.' },
  { l: 'l01', term: 'Southern Colonies', def: 'Maryland, Virginia, North Carolina, South Carolina and Georgia. Plantation economies built on cash crops and, increasingly, enslaved labor.', why: 'Most economically stratified and least diversified region.' },
  { l: 'l01', term: 'Chesapeake Colonies', def: 'Virginia and Maryland, around Chesapeake Bay. Built on tobacco, first with indentured servants and later with enslaved Africans.', why: 'Maryland is Chesapeake/Southern, not Middle. A common trap.' },
  { l: 'l01', term: 'Cash crop', def: 'A crop grown to sell for profit rather than to feed the farmer’s family: tobacco, rice, indigo, later cotton.', why: 'Cash crops drove the South’s demand for enslaved labor.' },
  { l: 'l01', term: 'Cereal crop', def: 'Grain crops such as wheat, corn and oats. Grown mainly in the Middle Colonies.', why: 'Made the Middle Colonies the “breadbasket” and supported family farms instead of plantations.' },
  { l: 'l01', term: 'Plantation agriculture', def: 'Large farms growing a single cash crop for export, worked by many laborers, usually enslaved.', why: 'Concentrated wealth and power in a planter elite.' },
  { l: 'l01', term: 'Indentured servitude', def: 'Poor Europeans agreed to work 4–7 years in exchange for passage to America, then were freed.', why: 'Main Chesapeake labor source until planters shifted to slavery after Bacon’s Rebellion (1676).' },
  { l: 'l01', term: 'Puritanism', def: 'English Protestants who wanted to “purify” the Church of England; founded Massachusetts Bay as a “city upon a hill.”', why: 'Shaped New England’s town meetings, education and religious intolerance.' },
  { l: 'l01', term: 'Mercantilism', def: 'Economic theory that a nation grows rich by exporting more than it imports; colonies exist to supply raw materials and buy the mother country’s goods.', why: 'Explains why Britain wanted colonies and passed the Navigation Acts.' },
  { l: 'l01', term: 'Navigation Acts', def: 'Laws starting in 1651 requiring colonial trade to use English ships and sending key goods only to England.', why: 'Mercantilism in action; loosely enforced during salutary neglect.' },
  { l: 'l01', term: 'Salutary neglect', def: 'Britain’s policy (c. 1690–1763) of loosely enforcing trade laws and leaving the colonies to govern themselves.', why: 'Gave colonists decades of self-government, so post-1763 taxes felt like a violation of their rights.' },
  { l: 'l01', term: 'House of Burgesses', def: 'Virginia’s elected assembly, founded in 1619. The first representative legislature in the English colonies.', why: 'An early root of American self-government.' },
  // L2
  { l: 'l02', term: 'French and Indian War', aka: ['Seven Years War', 'Seven Years’ War'], def: 'War from 1754 to 1763 between Britain and France (with Native allies) over the Ohio River Valley. Britain won.', why: 'Left Britain deeply in debt, which led to new colonial taxes and the end of salutary neglect.' },
  { l: 'l02', term: 'Albany Plan of Union', def: 'Benjamin Franklin’s 1754 plan for a united colonial government; every colony rejected it.', why: 'Shows the colonies didn’t yet see themselves as one people.' },
  { l: 'l02', term: 'Treaty of Paris (1763)', def: 'Ended the French and Indian War. France lost its North American mainland empire; Britain gained Canada and land to the Mississippi.', why: 'Removed the French threat, so colonists depended on Britain less.' },
  { l: 'l02', term: 'Proclamation of 1763', def: 'British order banning colonial settlement west of the Appalachian Mountains to avoid wars with Native nations.', why: 'Angered colonists who had fought for that land; an early grievance.' },
  { l: 'l02', term: 'Sugar Act', aka: ['Sugar Act, 1764'], def: '1764 law that lowered the tax on molasses but strictly enforced it, trying smugglers in vice-admiralty courts without juries.', why: 'First act clearly meant to raise revenue from the colonies.' },
  { l: 'l02', term: 'Quartering Act', aka: ['Quartering Act of 1765'], def: '1765 law requiring colonies to house and supply British troops.', why: 'Colonists feared a standing army in peacetime; later echoed in the 3rd Amendment.' },
  { l: 'l02', term: 'Stamp Act', aka: ['Stamp Act of 1765'], def: '1765 direct tax on printed materials: newspapers, legal documents, playing cards. Repealed in 1766.', why: 'Sparked “no taxation without representation,” the Stamp Act Congress and widespread boycotts.' },
  { l: 'l02', term: 'Virtual representation', def: 'British claim that Parliament represented all British subjects, including colonists who couldn’t vote for its members.', why: 'Colonists rejected it, demanding actual representation.' },
  { l: 'l02', term: 'Declaratory Act', def: '1766 law, passed with the Stamp Act repeal, asserting Parliament’s right to legislate for the colonies “in all cases whatsoever.”', why: 'Parliament backed down on the tax but not the principle.' },
  { l: 'l02', term: 'Townshend Acts', def: '1767 taxes on imported glass, lead, paint, paper and tea.', why: 'Revived boycotts; all repealed in 1770 except the tea tax.' },
  { l: 'l02', term: 'Boston Massacre', def: '1770 clash in which British soldiers killed five colonists. Paul Revere’s engraving made it propaganda.', why: 'Inflamed anti-British feeling; a classic example of source bias.' },
  { l: 'l02', term: 'Tea Act', aka: ['Tea Act, 1773'], def: '1773 law giving the British East India Company a monopoly on colonial tea sales. Tea got cheaper, but the tax remained.', why: 'Colonists resisted on principle, leading to the Boston Tea Party.' },
  { l: 'l02', term: 'Boston Tea Party', aka: ['Boston Tea Party, 1773'], def: 'December 1773: colonists dumped 342 chests of East India Company tea into Boston Harbor.', why: 'Triggered the Coercive (Intolerable) Acts.' },
  { l: 'l02', term: 'Coercive Acts', aka: ['Intolerable Acts'], def: '1774 laws punishing Boston: closed the harbor, restricted Massachusetts self-government, expanded quartering.', why: 'United the colonies against Britain and led to the First Continental Congress.' },
  { l: 'l02', term: 'First Continental Congress', def: '1774 meeting of 12 colonies in Philadelphia; organized a boycott and petitioned the king.', why: 'First major step toward unified colonial resistance.' },
  { l: 'l02', term: 'Second Continental Congress', def: 'Met from May 1775; created the Continental Army under Washington and declared independence in 1776.', why: 'Became the colonies’ wartime government.' },
  { l: 'l02', term: 'Committees of Correspondence', def: 'Networks of colonial leaders who shared news and coordinated resistance by letter, starting in 1772.', why: 'Built communication and unity among colonies.' },
  // L3
  { l: 'l03', term: 'Enlightenment', def: '17th–18th-century intellectual movement that applied reason to society and government.', why: 'Provided the ideas of natural rights, the social contract and separation of powers behind the Revolution.' },
  { l: 'l03', term: 'Natural rights', def: 'Rights every person is born with, which no government can take away. Locke named life, liberty and property.', why: 'Core idea of the Declaration of Independence.' },
  { l: 'l03', term: 'Social contract', def: 'The idea that people agree to be governed in exchange for protection of their rights; if government breaks the deal, people may replace it.', why: 'Justified the American Revolution.' },
  { l: 'l03', term: 'Common Sense', def: 'Thomas Paine’s January 1776 pamphlet attacking monarchy and urging independence in plain language.', why: 'Shifted public opinion from reconciliation to independence.' },
  { l: 'l03', term: 'Declaration of Independence', def: 'Adopted July 4, 1776; written mainly by Jefferson. Asserted natural rights, listed grievances against the king and declared independence.', why: 'Its promise that “all men are created equal” was invoked by later movements for equality.' },
  { l: 'l03', term: 'Thomas Jefferson', def: 'Virginia planter, author of the Declaration, leader of the Democratic-Republicans, 3rd president (1801–1809).', why: 'Symbol of both American ideals and their contradictions (he enslaved over 600 people).' },
  { l: 'l03', term: 'Three branches of government', def: 'Legislative (makes laws), executive (enforces laws) and judicial (interprets laws). Montesquieu’s idea.', why: 'Basis of separation of powers in state constitutions and the U.S. Constitution.' },
  { l: 'l03', term: 'Gradual emancipation', def: 'Laws freeing enslaved people slowly, usually children born after a certain date once they reached adulthood. Pennsylvania passed the first in 1780.', why: 'How most Northern states ended slavery, which slowly created a free North and a slave South.' },
  { l: 'l03', term: 'Abolition', def: 'Ending slavery. Abolitionists sought to end it completely, often immediately.', why: 'Northern states began abolition after the Revolution; a national movement grew in the 1830s.' },
  { l: 'l03', term: 'Republicanism', def: 'The belief that government should be based on the consent of the people through elected representatives, with citizens putting the common good above self-interest.', why: 'A core ideal of the Revolution and the Constitution.' },
  // L4
  { l: 'l04', term: 'Articles of Confederation', def: 'First U.S. national constitution (adopted 1781): a unicameral Congress, one vote per state, no executive, no courts and no power to tax.', why: 'Its weaknesses led to the Constitutional Convention of 1787.' },
  { l: 'l04', term: 'Critical Period', def: 'The years 1781–1787 under the Articles, marked by debt, worthless currency, trade disputes and weakness abroad.', why: 'Convinced leaders that a stronger national government was needed.' },
  { l: 'l04', term: 'Shays’ Rebellion', aka: ['Shays Rebellion'], def: '1786–87 uprising of indebted Massachusetts farmers led by Daniel Shays; they closed courts and attacked the Springfield arsenal.', why: 'Exposed the Articles’ weakness and spurred the Constitutional Convention.' },
  { l: 'l04', term: 'Northwest Ordinance', def: '1787 law creating a process for territories to become states and banning slavery north of the Ohio River.', why: 'Major Articles success; precedent for Congress banning slavery in territories.' },
  { l: 'l04', term: 'Land Ordinance of 1785', def: 'Surveyed western lands into townships and reserved land for public schools.', why: 'Organized western settlement under the Articles.' },
  // L5
  { l: 'l05', term: 'Constitutional Convention', aka: ['Constitutional Convention, 1787'], def: '1787 meeting in Philadelphia that replaced the Articles with the Constitution.', why: 'Created the current U.S. government through a series of compromises.' },
  { l: 'l05', term: 'Great Compromise', aka: ['Connecticut Plan', 'Connecticut Compromise'], def: 'Roger Sherman’s plan: a bicameral Congress with a House based on population and a Senate with two members per state.', why: 'Resolved the big-state vs. small-state fight.' },
  { l: 'l05', term: 'Virginia Plan', def: 'Madison’s proposal for a strong government with a bicameral legislature based on population.', why: 'Favored large states.' },
  { l: 'l05', term: 'New Jersey Plan', def: 'William Paterson’s proposal for a unicameral legislature with equal representation for each state.', why: 'Favored small states.' },
  { l: 'l05', term: 'Electoral College', def: 'System for choosing the president: each state gets electors equal to its House seats plus two Senators.', why: 'A compromise between election by Congress and by popular vote; the House decides if no one has a majority.' },
  { l: 'l05', term: 'Three-Fifths Compromise', aka: ['3/5 Compromise'], def: 'Counted each enslaved person as three-fifths of a person for representation and taxation.', why: 'Gave slave states extra power in the House and Electoral College.' },
  { l: 'l05', term: 'Slave Trade Clause', def: 'Article I, Section 9: Congress could not ban the importation of enslaved people before 1808.', why: 'Protected the Atlantic slave trade for 20 years; Congress banned it in 1808.' },
  { l: 'l05', term: 'Fugitive Slave Clause', def: 'Article IV, Section 2: people escaping slavery into another state must be returned.', why: 'Made free states part of enforcing slavery.' },
  { l: 'l05', term: 'Federalism', def: 'Division of power between the national government and state governments.', why: 'Central principle of the Constitution; the debate over the balance runs through U.S. history.' },
  { l: 'l05', term: 'Checks and balances', def: 'Each branch can limit the others (veto, override, judicial review, impeachment, confirmation).', why: 'Prevents any one branch from becoming too powerful.' },
  { l: 'l05', term: 'Separation of powers', def: 'Splitting government power among legislative, executive and judicial branches.', why: 'Montesquieu’s idea; protects against tyranny.' },
  { l: 'l05', term: 'Tyranny of the majority', def: 'The danger that a majority will use its power to oppress a minority.', why: 'Why the framers built filters like the Senate, Electoral College and courts.' },
  { l: 'l05', term: 'Tyranny of the minority', def: 'The danger that a small group (a king, aristocracy or faction) will control government against the majority’s will.', why: 'Why the Constitution rests on popular consent and divided power.' },
  { l: 'l05', term: 'Republic', def: 'A government in which citizens elect representatives to make decisions.', why: 'The Constitution creates a representative republic, not a direct democracy.' },
  { l: 'l05', term: 'Bicameral', def: 'Having two legislative houses (the House and Senate).', why: 'Product of the Great Compromise.' },
  { l: 'l05', term: 'James Madison', def: 'Virginian “Father of the Constitution”; wrote the Virginia Plan, co-wrote the Federalist Papers, drafted the Bill of Rights; later a Democratic-Republican and 4th president.', why: 'Central figure of the founding era.' },
  { l: 'l05', term: 'Supremacy Clause', def: 'Article VI: the Constitution and federal laws are the supreme law of the land, overriding conflicting state laws.', why: 'Basis for federal power over states (McCulloch v. Maryland).' },
  // L6
  { l: 'l06', term: 'Federalists', aka: ['Federalist'], def: 'Supporters of ratifying the Constitution (1787–88): Hamilton, Madison, Jay. Later the name of Hamilton’s political party.', why: 'Argued a strong national government was needed after the Articles failed.' },
  { l: 'l06', term: 'Anti-Federalists', aka: ['Anti Federalists', 'Anti-Federalist'], def: 'Opponents of the Constitution (Patrick Henry, George Mason) who feared a strong central government and demanded a bill of rights.', why: 'Lost ratification but won the Bill of Rights.' },
  { l: 'l06', term: 'The Federalist Papers', aka: ['Federalist Papers'], def: '85 essays by Hamilton, Madison and Jay (1787–88) urging New York to ratify the Constitution.', why: 'Federalist No. 10 (factions and a large republic) and No. 51 (checks and balances) are key.' },
  { l: 'l06', term: 'Bill of Rights', def: 'The first ten amendments (1791), protecting individual liberties such as speech, religion, jury trial and reserved powers.', why: 'Created to win over Anti-Federalists.' },
  { l: 'l06', term: 'Enumerated powers', def: 'Powers specifically listed for Congress in the Constitution (Article I, Section 8).', why: 'Strict constructionists said Congress was limited to these.' },
  { l: 'l06', term: 'Implied powers', def: 'Powers not listed but reasonably implied by enumerated powers, justified by the Necessary and Proper Clause.', why: 'Used to justify the national bank (McCulloch v. Maryland).' },
  { l: 'l06', term: 'Reserved powers', def: 'Powers kept by the states or the people because they aren’t given to the federal government (10th Amendment).', why: 'Strict constructionists and states’-rights advocates relied on them.' },
  { l: 'l06', term: 'Necessary and Proper Clause', aka: ['Elastic Clause'], def: 'Article I, Section 8: Congress may make all laws “necessary and proper” for carrying out its powers.', why: 'Source of implied powers; central to the loose vs. strict construction debate.' },
  { l: 'l06', term: 'Efficacious', def: 'Effective; able to produce the intended result. Federalists wanted an efficacious (energetic, effective) national government.', why: 'Study guide vocab: sums up the Federalist case against the weak Articles.' },
  // L7
  { l: 'l07', term: 'First Party System', def: 'Federalists vs. Democratic-Republicans, about 1792–1824.', why: 'The first U.S. parties formed over Hamilton’s program and foreign policy.' },
  { l: 'l07', term: 'Democratic-Republicans', aka: ['Democratic Republicans'], def: 'Jefferson and Madison’s party: states’ rights, strict construction, agriculture, pro-French.', why: 'Won the presidency in 1800 and dominated until the 1820s.' },
  { l: 'l07', term: 'Hamilton’s Financial Plan', aka: ['Hamilton’s financial plan'], def: 'Pay the national debt at full value, assume state debts, create a national bank, and use tariffs and excise taxes.', why: 'Strengthened federal credit and power; sparked the first party divide.' },
  { l: 'l07', term: 'Bank of the United States', aka: ['National Bank'], def: 'National bank chartered in 1791 (and again in 1816) to hold federal funds and stabilize currency.', why: 'Center of debates over implied powers (1791, McCulloch 1819, Jackson’s Bank War 1832).' },
  { l: 'l07', term: 'Tariff', def: 'A tax on imported goods. Revenue tariffs raise money; protective tariffs shield domestic industry from foreign competition.', why: 'Divided North (pro-tariff) and South (anti-tariff), leading to nullification in 1832.' },
  { l: 'l07', term: 'Whiskey Rebellion', aka: ['Whiskey Rebellion, 1794'], def: '1794 revolt of western Pennsylvania farmers against the federal whiskey tax; Washington crushed it with about 13,000 troops.', why: 'Contrast with Shays’ Rebellion: proved the new government could enforce its laws.' },
  { l: 'l07', term: 'Farewell Address', aka: ['Washington’s Farewell Address', 'Washington’s Farewell Address, 1796'], def: 'Washington’s 1796 message warning against political parties, permanent foreign alliances and sectionalism.', why: 'Guided U.S. foreign policy for a century.' },
  { l: 'l07', term: 'Alien and Sedition Acts', aka: ['Alien and Sedition Acts, 1798'], def: '1798 Federalist laws lengthening naturalization, allowing deportation of aliens and criminalizing criticism of the government.', why: 'Prompted the Virginia and Kentucky Resolutions and the states’-rights/nullification idea.' },
  { l: 'l07', term: 'Virginia and Kentucky Resolutions', def: '1798–99 resolutions by Madison and Jefferson arguing states could judge federal laws unconstitutional.', why: 'Root of nullification (1832) and secession arguments (1860).' },
  { l: 'l07', term: 'Revolution of 1800', def: 'Jefferson’s election over Adams: the first peaceful transfer of power between rival parties.', why: 'Proved the republic could survive partisan conflict.' },
  // L8
  { l: 'l08', term: 'Strict constructionism', aka: ['Strict construction'], def: 'Reading the Constitution narrowly: the federal government may do only what is specifically listed.', why: 'Jefferson’s view; used against the national bank.' },
  { l: 'l08', term: 'Loose constructionism', aka: ['Loose construction'], def: 'Reading the Constitution broadly: the government may do whatever is reasonably implied by its powers.', why: 'Hamilton’s view; upheld in McCulloch v. Maryland.' },
  { l: 'l08', term: 'Judicial review', def: 'The power of courts to declare laws unconstitutional.', why: 'Established in Marbury v. Madison (1803); not written in the Constitution.' },
  { l: 'l08', term: 'Marbury v. Madison', aka: ['Marbury v. Madison (1803)', 'Marbury v Madison'], def: '1803 Supreme Court case in which Chief Justice Marshall struck down part of the Judiciary Act of 1789, establishing judicial review.', why: 'Made the Supreme Court a co-equal branch.' },
  { l: 'l08', term: 'McCulloch v. Maryland', aka: ['McCulloch v. Maryland (1819)', 'McCulloch v Maryland'], def: '1819 case: Congress had implied power to create a national bank, and states could not tax it.', why: 'Upheld loose construction and federal supremacy.' },
  { l: 'l08', term: 'Gibbons v. Ogden', aka: ['Gibbons v. Ogden (1824)', 'Gibbons v Ogden'], def: '1824 case: Congress’s power over interstate commerce (including navigation) overrides state monopolies.', why: 'Broad commerce power, later used for the New Deal and civil rights law.' },
  { l: 'l08', term: 'John Marshall', def: 'Federalist chief justice (1801–1835) whose rulings strengthened the Supreme Court and national government.', why: 'Kept Federalist ideas alive after the party died.' },
  { l: 'l08', term: 'Louisiana Purchase', def: '1803 purchase of France’s Louisiana Territory for $15 million, roughly doubling the U.S.', why: 'Jefferson bent his strict-construction principles; reopened the question of slavery in new lands.' },
  { l: 'l08', term: 'War of 1812', def: 'War with Britain (1812–1815) over impressment, trade and Native resistance; called the “Second War of Independence.”', why: 'Boosted nationalism; destroyed the Federalists after the Hartford Convention.' },
  { l: 'l08', term: 'Hartford Convention', def: '1814–15 meeting of New England Federalists opposing the War of 1812; some discussed secession.', why: 'Made Federalists look disloyal, and the party collapsed.' },
  // L9
  { l: 'l09', term: 'Franchise', aka: ['suffrage'], def: 'The right to vote.', why: 'Expanding and contracting the franchise is the core story of this unit.' },
  { l: 'l09', term: 'Mass democracy', def: 'Politics in which large numbers of ordinary people vote and participate: rallies, conventions, high turnout.', why: 'Emerged in the 1820s–1840s with universal white manhood suffrage.' },
  { l: 'l09', term: 'Property qualifications', def: 'Requirements to own land or property in order to vote or hold office.', why: 'Mostly eliminated for white men by the 1840s.' },
  { l: 'l09', term: 'Universal white manhood suffrage', aka: ['Universal male suffrage'], def: 'Voting rights for all adult white men regardless of property, achieved in most states by the 1840s.', why: 'Expanded democracy for white men while women and Black men remained excluded.' },
  { l: 'l09', term: 'Corrupt bargain', aka: ['Corrupt bargain of 1824'], def: 'Jackson’s charge that Clay helped John Quincy Adams win the 1824 House vote in exchange for becoming Secretary of State.', why: 'Split the Democratic-Republicans and fueled Jackson’s 1828 victory.' },
  { l: 'l09', term: 'National Republicans', def: 'Adams and Clay’s faction after 1824; became the core of the Whig Party.', why: 'Shows how the old party split into the Second Party System.' },
  { l: 'l09', term: 'Second Party System', def: 'Democrats vs. Whigs, about 1828–1854.', why: 'Era of mass parties; collapsed over slavery.' },
  { l: 'l09', term: 'Andrew Jackson', def: 'War hero and 7th president (1829–1837); champion of the “common man,” the Bank War, nullification and Indian Removal.', why: 'Expanded presidential power and gave his name to an era.' },
  { l: 'l09', term: 'Nullification', aka: ['Nullification Crisis'], def: 'The theory that a state can refuse to enforce federal laws it judges unconstitutional; tested by South Carolina in 1832.', why: 'Jackson threatened force; a precursor to secession.' },
  { l: 'l09', term: 'Bank War', def: 'Jackson’s 1832 veto of the Second Bank’s recharter and his removal of federal deposits.', why: 'Expanded use of the veto; contributed to the Panic of 1837.' },
  { l: 'l09', term: 'Spoils system', def: 'Rewarding party supporters with government jobs (“to the victor belong the spoils”).', why: 'Built party loyalty; led to Gilded Age patronage and the Pendleton Act (1883).' },
  { l: 'l09', term: 'Whig Party', aka: ['Whigs'], def: 'Party formed in the 1830s against “King Andrew” Jackson, led by Henry Clay; supported the American System.', why: 'Collapsed after the Kansas-Nebraska Act split it over slavery.' },
  { l: 'l09', term: 'Democrats', aka: ['Democratic Party'], def: 'Jackson’s party (from 1828): limited federal government, states’ rights, the common man, against the national bank.', why: 'The oldest continuing U.S. party.' },
  { l: 'l09', term: 'American System', def: 'Henry Clay’s plan: a national bank, protective tariff and federally funded internal improvements.', why: 'The Whig economic program.' },
  { l: 'l09', term: 'Tariff of Abominations', def: 'The high protective tariff of 1828, hated in the South.', why: 'Triggered the nullification crisis.' },
  { l: 'l09', term: 'Indian Removal Act', def: '1830 law authorizing the forced relocation of Southeastern Native nations west of the Mississippi.', why: 'Led to the Trail of Tears (1838); Jackson ignored Worcester v. Georgia.' },
  // L10
  { l: 'l10', term: 'Missouri Compromise', def: '1820: Missouri admitted as a slave state, Maine as a free state; slavery banned in the Louisiana Purchase north of 36°30′.', why: 'Kept sectional peace for about 30 years; repealed by Kansas-Nebraska (1854).' },
  { l: 'l10', term: 'Mexican Cession', def: 'Land Mexico gave up in 1848 (California, Nevada, Utah, most of Arizona, part of New Mexico) for $15 million.', why: 'Reopened the slavery-expansion fight.' },
  { l: 'l10', term: 'Wilmot Proviso', def: '1846 proposal to ban slavery in any land taken from Mexico; passed the House but failed in the Senate.', why: 'Votes split by section, not party: a sign the party system was cracking.' },
  { l: 'l10', term: 'Compromise of 1850', def: 'California free; popular sovereignty in Utah and New Mexico; a harsher Fugitive Slave Act; slave trade banned in D.C.; Texas boundary settled.', why: 'Calmed tensions short-term but inflamed the North via the Fugitive Slave Act.' },
  { l: 'l10', term: 'Fugitive Slave Act', def: '1850 law forcing Northerners to help capture people escaping slavery; the accused had no jury trial or right to testify.', why: 'Turned many Northerners against slavery; inspired Uncle Tom’s Cabin.' },
  { l: 'l10', term: 'Popular sovereignty', def: 'Letting the settlers of a territory vote on whether to allow slavery.', why: 'Douglas’s “democratic” solution; it led to Bleeding Kansas.' },
  { l: 'l10', term: 'Sectionalism', def: 'Loyalty to one’s region (North, South or West) over the nation as a whole.', why: 'Washington warned against it; by the 1850s it defined politics.' },
  { l: 'l10', term: 'Uncle Tom’s Cabin', def: 'Harriet Beecher Stowe’s 1852 antislavery novel.', why: 'Turned many Northerners against slavery; enraged the South.' },
  // L11
  { l: 'l11', term: 'Free Soil Party', aka: ['Free Soil', 'Free Soilers', 'Free Democrats'], def: 'Party formed in 1848 to stop slavery’s expansion into the territories (not to abolish it where it existed).', why: 'Often motivated by protecting white labor, not Black rights; merged into the Republicans.' },
  { l: 'l11', term: 'Kansas-Nebraska Act', def: '1854 law by Stephen Douglas organizing Kansas and Nebraska under popular sovereignty, repealing the Missouri Compromise line.', why: 'Destroyed the Whigs, created the Republican Party and led to Bleeding Kansas.' },
  { l: 'l11', term: 'Bleeding Kansas', def: 'Violence in Kansas (1854–1859) between pro- and antislavery settlers, including the Sack of Lawrence and John Brown’s Pottawatomie killings.', why: 'Showed popular sovereignty failing; deepened sectional hatred.' },
  { l: 'l11', term: 'Dred Scott v. Sandford', aka: ['Dred Scott v Sanford', 'Dred Scott', 'Dred Scott case'], def: '1857 ruling: Black Americans were not citizens; enslaved people were property; Congress could not ban slavery in territories.', why: 'Declared the Missouri Compromise unconstitutional and threatened the Republican platform.' },
  { l: 'l11', term: 'Republican Party', def: 'Founded in 1854 in opposition to the Kansas-Nebraska Act; aimed to stop slavery’s expansion.', why: 'A sectional Northern party; won the presidency with Lincoln in 1860.' },
  { l: 'l11', term: 'John Brown', def: 'Radical abolitionist who killed pro-slavery settlers in Kansas (1856) and raided Harpers Ferry (1859).', why: 'Martyr to many Northerners; terrifying to the South.' },
  // L12
  { l: 'l12', term: 'Abraham Lincoln', aka: ['Abe Lincoln'], def: 'Republican elected president in 1860; led the Union through the Civil War; issued the Emancipation Proclamation; assassinated in 1865.', why: 'His election triggered secession.' },
  { l: 'l12', term: 'Confederate States of America', aka: ['Confederacy'], def: 'Nation formed by 11 seceding Southern states (1861–1865), led by Jefferson Davis.', why: 'Its founders openly stated it rested on slavery.' },
  { l: 'l12', term: 'The Union', def: 'The United States government and loyal states during the Civil War.', why: 'Lincoln’s first war goal was preserving it.' },
  { l: 'l12', term: 'Border states', aka: ['Upper South'], def: 'Slave states that stayed in the Union: Delaware, Maryland, Kentucky, Missouri (and West Virginia from 1863).', why: 'Keeping them loyal shaped Lincoln’s cautious early policy on slavery.' },
  { l: 'l12', term: 'Constitutional Union Party', def: '1860 party (John Bell) that avoided slavery and stood for preserving the Union.', why: 'Won Virginia, Kentucky and Tennessee.' },
  { l: 'l12', term: 'Secession', def: 'Formally withdrawing from the Union; begun by South Carolina in December 1860.', why: 'Southern states seceded to protect slavery after Lincoln’s election.' },
  { l: 'l12', term: 'Lost Cause', def: 'A myth, promoted from the late 1800s, that the Confederacy fought for states’ rights and honor rather than slavery.', why: 'Contradicted by the secession documents themselves.' },
  // L13
  { l: 'l13', term: 'Emancipation Proclamation', def: 'Lincoln’s order, effective January 1, 1863, freeing enslaved people in areas in rebellion and allowing Black men to enlist.', why: 'Made ending slavery a war aim; kept Britain and France out; did not free people in the border states.' },
  { l: 'l13', term: 'Battle of Gettysburg', def: 'July 1–3, 1863 Union victory in Pennsylvania; the war’s largest battle and a turning point.', why: 'Ended Lee’s invasion of the North.' },
  { l: 'l13', term: 'Gettysburg Address', def: 'Lincoln’s November 1863 speech recasting the war as a struggle for equality and “a new birth of freedom.”', why: 'Tied the Union cause to the Declaration of Independence.' },
  { l: 'l13', term: 'Habeas corpus', def: 'The right of an arrested person to be brought before a judge to decide whether the detention is lawful.', why: 'Lincoln suspended it to hold suspected Confederate sympathizers, expanding wartime executive power.' },
  { l: 'l13', term: 'Homestead Act', def: '1862 law giving 160 acres of western land to settlers who farmed it for five years.', why: 'Part of the Republican program passed during the war.' },
  // L14
  { l: 'l14', term: 'Reconstruction', def: 'The period 1865–1877 of rebuilding the South and defining freedom for formerly enslaved people.', why: 'Brought major constitutional change, then retreat.' },
  { l: 'l14', term: 'Presidential Reconstruction', def: 'Lincoln’s and Johnson’s lenient plans (1863–1867): quick readmission and pardons for most Confederates.', why: 'Allowed Black Codes and ex-Confederates back in power.' },
  { l: 'l14', term: 'Congressional Reconstruction', aka: ['Radical Reconstruction'], def: 'Republican-led Congress’s plan (1867–1877): military districts, Black male suffrage, the 14th and 15th Amendments.', why: 'Created interracial democracy in the South.' },
  { l: 'l14', term: 'Radical Republicans', def: 'Republicans such as Thaddeus Stevens and Charles Sumner who wanted to transform the South and protect freedpeople’s rights.', why: 'Drove Congressional Reconstruction and Johnson’s impeachment.' },
  { l: 'l14', term: 'Black Codes', def: 'Southern state laws (1865–66) restricting freedpeople’s rights to work, move, own land and testify.', why: 'Recreated slavery-like conditions; angered the North and sparked Radical Reconstruction.' },
  { l: 'l14', term: 'Freedmen’s Bureau', aka: ['Freedmen\'s Bureau'], def: 'Federal agency (1865–1872) giving freedpeople food, schools, legal help and labor contracts.', why: 'Founded thousands of schools; underfunded and opposed by Johnson.' },
  { l: 'l14', term: 'Reconstruction Acts', aka: ['Reconstruction Act of 1867'], def: '1867 laws dividing the South into five military districts and requiring Black male suffrage and ratification of the 14th Amendment.', why: 'Heart of Congressional Reconstruction.' },
  { l: 'l14', term: '13th Amendment', def: '1865: abolished slavery, “except as a punishment for crime.”', why: 'Ended slavery; its loophole enabled convict leasing.' },
  { l: 'l14', term: '14th Amendment', def: '1868: citizenship for all born in the U.S.; equal protection and due process from the states.', why: 'Overturned Dred Scott; basis of Brown v. Board and modern civil rights.' },
  { l: 'l14', term: '15th Amendment', def: '1870: the vote cannot be denied based on race, color or previous condition of servitude.', why: 'Evaded by Jim Crow until the Voting Rights Act of 1965.' },
  { l: 'l14', term: 'Reconstruction Amendments', def: 'The 13th, 14th and 15th Amendments.', why: 'A “second founding” protecting rights against states.' },
  { l: 'l14', term: 'Andrew Johnson', def: 'Tennessee Democrat who became president after Lincoln’s assassination; impeached in 1868, acquitted by one vote.', why: 'His lenient, racist policies provoked Radical Reconstruction.' },
  // L15
  { l: 'l15', term: 'Interracial democracy', def: 'Black and white citizens voting and governing together in the Reconstruction South.', why: 'About 2,000 Black officeholders; destroyed by violence after 1877.' },
  { l: 'l15', term: 'Universal public education', def: 'Tax-supported schools open to all children; first created in the South by Reconstruction governments.', why: 'A lasting Reconstruction achievement.' },
  { l: 'l15', term: 'Hiram Revels', def: 'Mississippi senator and the first Black U.S. senator (1870).', why: 'Symbol of interracial democracy.' },
  { l: 'l15', term: 'Ku Klux Klan', aka: ['Klu Klux Klan', 'KKK'], def: 'White supremacist terrorist group founded in 1865 in Tennessee by Confederate veterans; attacked Black voters and Republicans.', why: 'Political violence was the main weapon that ended Reconstruction.' },
  { l: 'l15', term: 'Sharecropping', def: 'Landowners provided land and tools; workers paid with a share of the crop and often fell into debt.', why: 'Kept freedpeople poor and tied to the land.' },
  { l: 'l15', term: 'Peonage', def: 'Debt slavery: being forced to work to pay off a debt.', why: 'Trapped sharecroppers; continued despite an 1867 ban.' },
  { l: 'l15', term: 'Convict leasing', def: 'States leased prisoners, mostly Black men arrested on minor charges, as unpaid labor to businesses.', why: '“Slavery by another name,” enabled by the 13th Amendment loophole.' },
  { l: 'l15', term: 'Compromise of 1877', aka: ['Corrupt Bargain of 1877', '“Compromise” of 1877'], def: 'Deal settling the disputed 1876 election: Hayes became president and federal troops left the South.', why: 'Ended Reconstruction.' },
  { l: 'l15', term: 'Enforcement Acts', def: '1870–71 laws (including the Ku Klux Klan Act) letting the federal government prosecute racial violence.', why: 'Grant used them to break the first Klan.' },
  { l: 'l15', term: 'Redeemers', def: 'White Southern Democrats who “redeemed” states from Republican rule in the 1870s.', why: 'Restored white supremacy and laid the groundwork for Jim Crow.' },
  // L16
  { l: 'l16', term: 'Jim Crow', aka: ['Jim Crow Segregation'], def: 'The system of laws, customs and violence enforcing racial segregation and white supremacy, about 1877–1965.', why: 'Made Black Southerners second-class citizens for nearly a century.' },
  { l: 'l16', term: 'Segregation', def: 'Separation of people by race in public places, schools and services.', why: 'Legalized by Plessy, outlawed by Brown and the Civil Rights Act of 1964.' },
  { l: 'l16', term: 'Poll tax', aka: ['Poll Taxes'], def: 'A fee required to vote.', why: 'Disenfranchised poor Black (and white) voters; banned in federal elections by the 24th Amendment (1964).' },
  { l: 'l16', term: 'Literacy test', aka: ['Literacy Tests'], def: 'A reading or “interpretation” test for voters, applied by white registrars to fail Black applicants.', why: 'Got around the 15th Amendment; banned by the Voting Rights Act.' },
  { l: 'l16', term: 'Grandfather clause', def: 'Exempted men from voting tests if their grandfathers could vote before 1867.', why: 'Protected white voters; struck down in 1915.' },
  { l: 'l16', term: 'Plessy v. Ferguson', aka: ['Plessy vs Ferguson', 'Plessy v Ferguson'], def: '1896 Supreme Court ruling that state-mandated segregation was constitutional if facilities were “separate but equal.”', why: 'Legalized Jim Crow until Brown v. Board (1954).' },
  { l: 'l16', term: 'Separate but equal', def: 'The Plessy doctrine allowing segregation if facilities were equal. In practice they almost never were.', why: 'Overturned for schools in Brown (1954).' },
  { l: 'l16', term: 'One-drop rule', def: 'The rule that a person with any Black ancestry was legally Black.', why: 'Homer Plessy, seven-eighths white, was classified as Black.' },
  { l: 'l16', term: 'Lynching', def: 'Public murder by a mob without trial; thousands of Black Americans were lynched between 1877 and 1950.', why: 'The terror underpinning Jim Crow.' },
  // L17
  { l: 'l17', term: 'Gilded Age', def: 'About 1870–1900: rapid industrialization and great fortunes masking corruption, poverty and inequality.', why: 'Its problems sparked the Populists and Progressives.' },
  { l: 'l17', term: 'Political machines', aka: ['Political machine', 'Machine politics'], def: 'Party organizations that controlled city governments by trading jobs and services for votes.', why: 'Provided help to immigrants but bred corruption.' },
  { l: 'l17', term: 'Patronage', def: 'Giving government jobs and favors to political supporters.', why: 'Fueled machines; reformed by the Pendleton Act (1883).' },
  { l: 'l17', term: 'Party boss', aka: ['Party Bosses'], def: 'The powerful leader of a political machine.', why: 'Boss Tweed is the classic example.' },
  { l: 'l17', term: 'Boss Tweed', def: 'William Tweed, leader of New York’s Tammany Hall machine; stole millions; exposed by Thomas Nast’s cartoons.', why: 'Symbol of Gilded Age corruption.' },
  { l: 'l17', term: 'Crédit Mobilier', aka: ['Credit Mobilier'], def: 'Scandal revealed in 1872: Union Pacific insiders overcharged the railroad and bribed congressmen with stock.', why: 'Showed corruption reaching Congress and the vice president.' },
  { l: 'l17', term: 'Whiskey Ring', def: '1875 scandal: distillers and Treasury officials stole millions in whiskey taxes; Grant’s secretary was implicated.', why: 'One of the Grant administration scandals.' },
  { l: 'l17', term: 'Fourth Party System', def: 'About 1896–1932: Republican dominance after McKinley’s defeat of Bryan.', why: 'Covers the Progressive Era and 1920s.' },
  { l: 'l17', term: 'Laissez-faire', aka: ['Laissez-Faire'], def: 'The belief that government should not interfere in the economy.', why: 'Dominant in the Gilded Age and 1920s; rejected by the Progressives and the New Deal.' },
  { l: 'l17', term: 'Pendleton Civil Service Act', def: '1883 law requiring merit exams for some federal jobs, after Garfield’s assassination by a disappointed office-seeker.', why: 'Began reforming the spoils system.' },
  { l: 'l17', term: 'Populist Party', aka: ['Populists', 'People’s Party'], def: '1890s farmers’ party demanding free silver, an income tax, direct election of senators and railroad regulation.', why: 'Many of its ideas became Progressive reforms.' },
  // L18
  { l: 'l18', term: 'Progressives', aka: ['Progressive Era'], def: 'Reformers (about 1890–1920) who used government to fix problems of industrialization and corruption.', why: 'Produced the 16th–19th Amendments and antitrust laws.' },
  { l: 'l18', term: 'Muckrakers', aka: ['Muckraker'], def: 'Investigative journalists who exposed corruption and social problems (Tarbell, Sinclair, Steffens, Riis).', why: 'Created public pressure for reform.' },
  { l: 'l18', term: 'National American Woman Suffrage Association', aka: ['NAWSA'], def: 'Main women’s suffrage organization, formed in 1890; led by Carrie Chapman Catt.', why: 'Won the 19th Amendment with a state-by-state strategy.' },
  { l: 'l18', term: '16th Amendment', def: '1913: allowed a federal income tax.', why: 'Shifted revenue from tariffs to income; taxed the wealthy more.' },
  { l: 'l18', term: '17th Amendment', def: '1913: direct election of U.S. senators by voters.', why: 'Reduced corporate and boss influence over the Senate.' },
  { l: 'l18', term: '19th Amendment', def: '1920: women’s right to vote.', why: 'Largest single expansion of the franchise.' },
  { l: 'l18', term: 'Sherman Antitrust Act', def: '1890 law banning monopolies and combinations “in restraint of trade”; vague and weakly enforced, often used against unions.', why: 'First federal antitrust law.' },
  { l: 'l18', term: 'Clayton Antitrust Act', def: '1914 law listing specific illegal business practices and exempting labor unions.', why: 'Strengthened antitrust enforcement under Wilson.' },
  { l: 'l18', term: 'Theodore Roosevelt', aka: ['Teddy Roosevelt'], def: 'Republican president 1901–1909; Square Deal, trust-busting, consumer protection, conservation.', why: 'His 1904 election marks the start of the Progressive Era on your study guide.' },
  { l: 'l18', term: 'William Howard Taft', aka: ['William Taft'], def: 'Republican president 1909–1913; filed many antitrust suits; split with Roosevelt.', why: 'One of the three Progressive presidents.' },
  { l: 'l18', term: 'Woodrow Wilson', def: 'Democratic president 1913–1921; New Freedom: Federal Reserve, Clayton Act, lower tariff, income tax.', why: 'Third Progressive president; also segregated the federal workforce.' },
  // L19
  { l: 'l19', term: 'Direct relief', def: 'Government giving money or goods directly to people in need.', why: 'Hoover opposed it; the New Deal embraced it.' },
  { l: 'l19', term: 'Relief, Recovery, and Reform', aka: ['Three R’s', 'Relief, Recovery and Reform'], def: 'FDR’s New Deal goals: help people now, fix the economy, prevent future depressions.', why: 'The way to organize New Deal programs.' },
  { l: 'l19', term: 'AAA', aka: ['Agricultural Adjustment Act', 'Agriculture Adjustment Agency'], def: 'Paid farmers to produce less to raise crop prices (recovery).', why: 'Helped landowners; hurt sharecroppers; struck down in 1936 then revised.' },
  { l: 'l19', term: 'WPA', aka: ['Works Progress Administration'], def: 'Employed about 8.5 million people on public works and arts projects (relief).', why: 'Largest New Deal jobs program.' },
  { l: 'l19', term: 'NRA', aka: ['National Recovery Administration'], def: 'Set industry codes for wages, prices and hours (recovery); struck down by the Supreme Court in 1935.', why: 'Example of New Deal planning and its constitutional limits.' },
  { l: 'l19', term: 'SEC', aka: ['Securities and Exchange Commission'], def: 'Regulates the stock market (reform).', why: 'Prevents the kind of fraud that fed the 1929 crash.' },
  { l: 'l19', term: 'FDIC', aka: ['Federal Deposit Insurance Corporation'], def: 'Insures bank deposits (reform).', why: 'Ended bank runs; still exists.' },
  { l: 'l19', term: 'Social Security', aka: ['Social Security Act'], def: '1935 law creating old-age pensions and unemployment insurance (reform).', why: 'Foundation of the U.S. safety net; initially excluded farm and domestic workers.' },
  { l: 'l19', term: 'New Deal', def: 'FDR’s programs (1933–1939) responding to the Great Depression.', why: 'Permanently expanded the federal government’s role in the economy and welfare.' },
  { l: 'l19', term: 'Huey Long', def: 'Louisiana senator whose “Share Our Wealth” plan attacked the New Deal from the left.', why: 'Example of progressive/populist criticism.' },
  { l: 'l19', term: 'Fifth Party System', aka: ['New Deal coalition'], def: 'About 1932–1968: Democratic dominance through FDR’s coalition of labor, immigrants, Black voters and the white South.', why: 'Broke apart over civil rights in the 1960s.' },
  // L20
  { l: 'l20', term: 'Isaac Woodard', def: 'Black WWII veteran blinded by a South Carolina police chief in 1946; his attacker was acquitted.', why: 'Pushed Truman to act on civil rights.' },
  { l: 'l20', term: 'Executive Order 9981', aka: ['Desegregation of the military'], def: 'Truman’s 1948 order desegregating the armed forces.', why: 'Major early federal civil rights action, done without Congress.' },
  { l: 'l20', term: 'Thurgood Marshall', def: 'NAACP lawyer who won Brown v. Board; first Black Supreme Court justice (1967).', why: 'Architect of the legal assault on segregation.' },
  { l: 'l20', term: 'Brown v. Board of Education', aka: ['Brown v Board of Education', 'Brown v. Board'], def: '1954 unanimous ruling that segregated public schools are “inherently unequal.”', why: 'Overturned Plessy for education; a catalyst for the movement and white backlash.' },
  { l: 'l20', term: 'Little Rock Nine', def: 'Nine Black students who integrated Central High School in Little Rock, Arkansas in 1957, protected by federal troops.', why: 'First federal troops sent to protect Black rights since Reconstruction.' },
  { l: 'l20', term: 'Massive resistance', def: 'Southern campaign to block school integration after Brown, including the Southern Manifesto and school closures.', why: 'Showed the limits of court rulings without enforcement.' },
  { l: 'l20', term: 'Dixiecrats', def: 'Southern Democrats who left the party in 1948 to run Strom Thurmond, opposing Truman’s civil rights stance.', why: 'First crack in the Solid South.' },
  // L21
  { l: 'l21', term: 'Civil Rights Act of 1964', def: 'Banned segregation in public accommodations and employment discrimination by race, color, religion, sex or national origin.', why: 'Destroyed the legal pillar of Jim Crow.' },
  { l: 'l21', term: 'Voting Rights Act of 1965', def: 'Banned literacy tests, sent federal examiners and required federal preclearance of voting changes in covered areas.', why: 'Enforced the 15th Amendment; Black registration soared.' },
  { l: 'l21', term: '24th Amendment', def: '1964: banned poll taxes in federal elections.', why: 'Removed a key Jim Crow voting barrier.' },
  { l: 'l21', term: 'Equal Pay Act of 1963', aka: ['Equal Pay Act'], def: 'Required equal pay for men and women doing equal work.', why: 'Early federal action against sex discrimination.' },
  { l: 'l21', term: 'Title IX', aka: ['Title IX, 1972'], def: '1972 law banning sex discrimination in federally funded education programs.', why: 'Transformed opportunities for women, especially in sports.' },
  { l: 'l21', term: 'Shelby County v. Holder', def: '2013 ruling striking down the Voting Rights Act formula for preclearance.', why: 'Reopened debates over voting access.' },
  { l: 'l21', term: 'Lyndon B. Johnson', aka: ['LBJ'], def: 'Democratic president 1963–1969; passed the Civil Rights and Voting Rights Acts and the Great Society; escalated Vietnam.', why: 'Peak of the liberal consensus.' },
  // L22
  { l: 'l22', term: 'Credibility gap', def: 'Public disbelief in what government leaders say, especially about Vietnam and Watergate.', why: 'Trust in government fell from about 77% (1964) to about 25% (1980).' },
  { l: 'l22', term: 'Vietnam War', def: 'U.S. war (escalated 1964–1973) to stop communist North Vietnam from taking over South Vietnam.', why: 'Official deceptions created the credibility gap.' },
  { l: 'l22', term: 'Gulf of Tonkin Resolution', def: '1964 congressional resolution giving LBJ broad power to use force in Vietnam.', why: 'Based partly on an attack that likely never happened.' },
  { l: 'l22', term: '1968 Democratic Convention', aka: ['1968 Democratic National Convention'], def: 'Chicago convention where police violently clashed with antiwar protesters on live TV.', why: 'Showed a divided Democratic Party; helped Nixon win.' },
  { l: 'l22', term: 'Anti-war movement', aka: ['Anti War movement'], def: 'Protests against the Vietnam War: teach-ins, marches, draft resistance.', why: 'Pressured leaders and exposed deep national division.' },
  { l: 'l22', term: 'Kent State Massacre', aka: ['Kent State'], def: 'May 4, 1970: the Ohio National Guard killed four student protesters at Kent State University.', why: 'Government violence against its own citizens deepened distrust.' },
  { l: 'l22', term: 'Pentagon Papers', def: 'Secret Defense Department history of the Vietnam War leaked by Daniel Ellsberg and published in 1971.', why: 'Proved four administrations misled the public.' },
  { l: 'l22', term: 'Watergate', def: '1972 break-in at Democratic headquarters and Nixon’s cover-up, which led to his resignation in 1974.', why: 'Biggest blow to trust in government; showed checks and balances working.' },
  { l: 'l22', term: 'United States v. Nixon', def: '1974 unanimous ruling forcing Nixon to release the White House tapes.', why: 'No one, not even the president, is above the law.' },
  { l: 'l22', term: 'War Powers Resolution', def: '1973 law limiting the president’s ability to send troops abroad without Congress.', why: 'Congress reasserting power after Vietnam.' },
  // L23
  { l: 'l23', term: 'Liberal consensus', def: 'Post-WWII agreement in both parties that government should manage the economy and provide a safety net.', why: 'The New Right rose to challenge it.' },
  { l: 'l23', term: 'Great Society', def: 'LBJ’s 1964–65 programs: War on Poverty, Medicare, Medicaid, federal education aid.', why: 'Peak of liberalism; conservatives criticized its cost and reach.' },
  { l: 'l23', term: 'Affirmative action', def: 'Policies giving preference to minorities and women in hiring and admissions to remedy past discrimination.', why: 'Became a major conservative grievance.' },
  { l: 'l23', term: 'Barry Goldwater', def: 'Arizona senator and 1964 Republican nominee; opposed the New Deal and Civil Rights Act; lost in a landslide but launched modern conservatism.', why: 'Won five Deep South states, an early sign of realignment.' },
  { l: 'l23', term: 'Federal overreach', def: 'The conservative charge that the national government had taken power belonging to states, communities or individuals.', why: 'Core theme of conservative backlash (busing, regulations, court rulings).' },
  { l: 'l23', term: 'Southern Strategy', def: 'Republican strategy, especially Nixon’s in 1968, of winning white Southern voters through coded appeals like “law and order” and “states’ rights.”', why: 'Helped flip the white South to the Republican Party.' },
  { l: 'l23', term: 'Roe v. Wade', aka: ['Roe v Wade', 'Roe v Wade 1973'], def: '1973 Supreme Court ruling recognizing a constitutional right to abortion (overturned in 2022).', why: 'Mobilized the Religious Right.' },
  { l: 'l23', term: 'Moral Majority', def: 'Political organization founded by Jerry Falwell in 1979 to mobilize conservative Christians.', why: 'Key part of Reagan’s 1980 coalition.' },
  { l: 'l23', term: 'Religious Right', def: 'Politically active conservative Christians focused on “family values,” abortion and school prayer.', why: 'Became a core Republican voting bloc.' },
  { l: 'l23', term: 'Jerry Falwell', def: 'Televangelist and founder of the Moral Majority.', why: 'Linked evangelical Christianity to conservative politics.' },
  { l: 'l23', term: 'Ronald Reagan', def: 'Republican president 1981–1989; tax cuts, deregulation, defense buildup: “government is the problem.”', why: 'His 1980 election marks the triumph of the New Right.' },
  { l: 'l23', term: 'Movement Conservatism', aka: ['Movement conservatism', 'New Right'], def: 'Coalition of economic conservatives, social/religious conservatives and anti-communists that rose from the 1960s to 1980.', why: 'Rejected the liberal consensus; brought Reagan to power.' },
  { l: 'l23', term: 'Sun Belt', def: 'Southern and Southwestern states that grew rapidly after WWII (Florida to California).', why: 'Shifted population, House seats and electoral votes toward conservative regions.' },
  { l: 'l23', term: 'Reaganomics', aka: ['Supply-side economics'], def: 'Reagan’s economic policy: tax cuts, deregulation, reduced domestic spending and a defense buildup.', why: 'The national debt roughly tripled.' },
  { l: 'l23', term: 'Sixth Party System', def: 'About 1968–present: realignment as the white South moved to the Republican Party.', why: 'Result of the civil rights era and the Southern Strategy.' },
  { l: 'l23', term: 'George Wallace', def: 'Alabama governor (“segregation forever”) who ran as a third-party candidate in 1968 and won five Southern states.', why: 'Showed white Southern voters were ready to leave the Democrats.' }
];

window.DATES = [
  { y: '1754', e: 'Start of the French and Indian War (aka Seven Years’ War)', note: 'Fought over the Ohio River Valley; Britain’s war debt leads to colonial taxes.' },
  { y: '1776', e: 'Declaration of Independence', note: 'July 4, 1776. Jefferson, natural rights, consent of the governed.' },
  { y: '1781', e: 'Articles of Confederation adopted', note: 'First national government: no executive, no power to tax.' },
  { y: '1789', e: 'Constitution ratified / goes into effect', note: 'Washington becomes the first president.' },
  { y: '1796', e: 'Washington’s Farewell Address', note: 'Warns against parties, permanent alliances and sectionalism.' },
  { y: '1800', e: 'First peaceful transition of power (“Revolution of 1800”)', note: 'Jefferson (Democratic-Republican) defeats Adams (Federalist).' },
  { y: '1812', e: 'War of 1812 (“Second War of Independence”)', note: 'Federalists collapse after the Hartford Convention.' },
  { y: '1820', e: 'Missouri Compromise', note: 'Missouri slave, Maine free, 36°30′ line.' },
  { y: '1828', e: 'Election of Andrew Jackson', note: 'The “common man” president; start of the Second Party System.' },
  { y: '1832', e: 'Jackson’s nullification crisis; Jackson kills the national bank', note: 'South Carolina nullifies the tariff; Jackson vetoes the Bank recharter.' },
  { y: '1850', e: 'Compromise of 1850', note: 'California free; harsher Fugitive Slave Act; popular sovereignty.' },
  { y: '1854', e: 'Kansas-Nebraska Act; founding of the Republican Party', note: 'Repeals the Missouri Compromise line; Bleeding Kansas follows.' },
  { y: '1860', e: 'Election of Abraham Lincoln', note: 'Wins with about 40% of the vote; Southern secession begins.' },
  { y: '1863', e: 'Gettysburg Address; Emancipation Proclamation', note: 'The war becomes a fight for freedom and “a new birth of freedom.”' },
  { y: '1865', e: 'End of the Civil War; start of Reconstruction', note: '13th Amendment; Lincoln assassinated.' },
  { y: '1877', e: 'Compromise of 1877; Reconstruction ends', note: 'Hayes becomes president; federal troops leave the South.' },
  { y: '1896', e: 'Plessy v. Ferguson', note: '“Separate but equal” makes segregation legal.' },
  { y: '1904', e: 'Election of Teddy Roosevelt (beginning of the Progressive Era)', note: 'Square Deal, trust-busting, consumer protection.' },
  { y: '1932', e: 'FDR elected; New Deal', note: 'Relief, Recovery, Reform; the federal government’s role expands.' },
  { y: '1954', e: 'Brown v. Board of Education', note: 'Segregated schools “inherently unequal”; overturns Plessy for schools.' },
  { y: '1973', e: 'Roe v. Wade; Watergate', note: 'Mobilizes the Religious Right; collapse of trust in government.' },
  { y: '1980', e: 'Election of Ronald Reagan', note: 'Triumph of movement conservatism: “government is the problem.”' }
];
